//! The function table, loaded at run time.
//!
//! Two data files:
//! - `schemas/script/functions.json` (`fnv.script.functions/1`, generated by
//!   `tools/capture/script_functions.py`): names, aliases, documented parameters, calling
//!   reference, opcodes, condition indices, use counts, Begin-block names.
//! - `crates/fnv-script/data/encodings.json` (`fnv.script.encodings/1`, compiled into
//!   the crate): how each parameter of a function is encoded in the bytecode where that
//!   is not the default tagged value, and the spellings of enumerated codes. Every entry
//!   is observed in the shipped masters (docs/spec-notes/scripts.md §2.4).
//!
//! The interpreter dispatches on opcode; names are for diagnostics and the decompiler.

use serde_json::Value;
use std::collections::{BTreeMap, HashMap};
use std::path::Path;

/// The first opcode given to console functions, which the catalogue lists without one
/// (they are typed at the console, never compiled into a shipped script). They take
/// `CONSOLE_OPCODE_BASE + i`, `i` their place among those functions in case-insensitive
/// name order [decision: our numbering, outside the 0x1000–0x1FFF range scripts use; a
/// function the catalogue gains moves the later ones, which the function registry's
/// name test catches]. docs/design/console.md.
pub const CONSOLE_OPCODE_BASE: u16 = 0xF000;

/// The encodings file compiled into the crate.
pub const ENCODINGS_JSON: &str = include_str!("../data/encodings.json");

#[derive(Debug, thiserror::Error)]
pub enum TableError {
    #[error("{0}: {1}")]
    Io(String, std::io::Error),
    #[error("{0}: {1}")]
    Json(String, serde_json::Error),
    #[error("{0}")]
    Format(String),
}

/// How one parameter is encoded (docs/spec-notes/scripts.md §2.4).
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ParamEnc {
    /// A tagged value: `r`, `n`, `z`, `s`, `f`, `G`, or `r` + `s`/`f`.
    Value,
    /// A bare u16 code of the named enumeration (`actor_value`, `anim_group`, …).
    Enum(String),
    /// One ASCII byte `X`/`Y`/`Z`.
    Axis,
    /// u16 length + bytes.
    String,
}

/// What follows the parameters of a formatted-message function.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TrailerEnc {
    /// u16 count + that many tagged values.
    FormatVars,
    /// An untagged i32.
    Int32,
}

/// Where a function's parameter encodings come from.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EncodingSource {
    /// Observed in shipped bytecode: listed in encodings.json, or called by shipped
    /// scripts with tagged values only.
    Observed,
    /// Derived from the xEdit condition parameter types by the rule in encodings.json
    /// (`xedit_types`), for functions shipped scripts never call [hypothesis].
    XeditType,
    /// Every parameter a tagged value (the rule for all other functions).
    Default,
}

#[derive(Debug, Clone)]
pub struct Param {
    pub name: String,
    /// The wiki's free-form type text.
    pub wiki_type: Option<String>,
    /// The catalogue's normalised kind (`int`, `reference`, …).
    pub kind: String,
    pub optional: bool,
}

#[derive(Debug, Clone)]
pub struct Function {
    pub opcode: u16,
    pub name: String,
    pub aliases: Vec<String>,
    pub observed_spellings: Vec<String>,
    pub params: Vec<Param>,
    pub calling_reference: Option<String>,
    pub condition_index: Option<u16>,
    pub script_calls: u64,
    pub scripts_using: u64,
    pub condition_uses: u64,
    pub console_only: bool,
    pub encodings: Vec<ParamEnc>,
    pub trailer: Vec<TrailerEnc>,
    pub encoding_source: EncodingSource,
    /// Parameters the compiler takes when the shipped calls show more than the catalogue
    /// documents (encodings.json `compiler.param_counts`).
    pub param_count: Option<usize>,
    /// Whether a call has a parameter block, where the catalogue's list would say
    /// otherwise (encodings.json `compiler.block`).
    pub block: Option<bool>,
    /// Parameter positions whose numbers are stored as floats (`true`) or integers
    /// (`false`) against the catalogue's kind (encodings.json `compiler.number_types`).
    pub number_types: BTreeMap<usize, bool>,
}

#[derive(Debug, Clone, Default)]
pub struct FunctionTable {
    pub functions: BTreeMap<u16, Function>,
    /// Begin-block event code → block name.
    pub blocks: BTreeMap<u16, String>,
    /// Enumeration → code → spelling used in shipped source.
    pub enums: BTreeMap<String, BTreeMap<u16, String>>,
    /// Begin events whose statement has a parameter block (encodings.json
    /// `compiler.begin_params`).
    pub begin_params: std::collections::BTreeSet<u16>,
    by_name: HashMap<String, u16>,
}

fn parse_hex16(s: &str) -> Option<u16> {
    u16::from_str_radix(s.strip_prefix("0x").or_else(|| s.strip_prefix("0X")).unwrap_or(s), 16).ok()
}

fn parse_enc(s: &str) -> Result<ParamEnc, TableError> {
    Ok(match s {
        "value" => ParamEnc::Value,
        "axis" => ParamEnc::Axis,
        "string" => ParamEnc::String,
        _ => match s.strip_prefix("enum:") {
            Some(k) if !k.is_empty() => ParamEnc::Enum(k.to_string()),
            _ => return Err(TableError::Format(format!("unknown parameter encoding {s:?}"))),
        },
    })
}

fn parse_trailer(s: &str) -> Result<TrailerEnc, TableError> {
    match s {
        "format_vars" => Ok(TrailerEnc::FormatVars),
        "int32" => Ok(TrailerEnc::Int32),
        _ => Err(TableError::Format(format!("unknown trailer encoding {s:?}"))),
    }
}

fn strings(v: Option<&Value>) -> Vec<String> {
    v.and_then(Value::as_array)
        .map(|a| a.iter().filter_map(|x| x.as_str().map(str::to_string)).collect())
        .unwrap_or_default()
}

impl FunctionTable {
    /// Load `functions.json` from disk, with the compiled-in encodings.
    pub fn load(functions_json: &Path) -> Result<FunctionTable, TableError> {
        let label = functions_json.display().to_string();
        let text = std::fs::read_to_string(functions_json).map_err(|e| TableError::Io(label.clone(), e))?;
        Self::from_json(&text, ENCODINGS_JSON).map_err(|e| match e {
            TableError::Format(m) => TableError::Format(format!("{label}: {m}")),
            other => other,
        })
    }

    /// Build the table from the text of both files.
    pub fn from_json(functions: &str, encodings: &str) -> Result<FunctionTable, TableError> {
        let f: Value = serde_json::from_str(functions).map_err(|e| TableError::Json("functions".into(), e))?;
        let e: Value = serde_json::from_str(encodings).map_err(|e| TableError::Json("encodings".into(), e))?;
        if f.get("schema").and_then(Value::as_str) != Some("fnv.script.functions/1") {
            return Err(TableError::Format("functions: not fnv.script.functions/1".into()));
        }
        if e.get("format").and_then(Value::as_str) != Some("fnv.script.encodings/1") {
            return Err(TableError::Format("encodings: not fnv.script.encodings/1".into()));
        }
        let mut t = FunctionTable::default();
        for b in f.get("begin_blocks").and_then(Value::as_array).into_iter().flatten() {
            if let (Some(code), Some(name)) =
                (b.get("code").and_then(Value::as_str).and_then(parse_hex16), b.get("block").and_then(Value::as_str))
            {
                t.blocks.insert(code, name.to_string());
            }
        }
        // Encodings: observed per-function lists, and the xEdit-type rule.
        let mut observed: HashMap<u16, (Vec<ParamEnc>, Vec<TrailerEnc>)> = HashMap::new();
        for (k, v) in e.get("functions").and_then(Value::as_object).into_iter().flatten() {
            let op = parse_hex16(k).ok_or_else(|| TableError::Format(format!("encodings: bad opcode {k:?}")))?;
            let params = strings(v.get("params")).iter().map(|s| parse_enc(s)).collect::<Result<Vec<_>, _>>()?;
            let trailer = strings(v.get("trailer")).iter().map(|s| parse_trailer(s)).collect::<Result<Vec<_>, _>>()?;
            observed.insert(op, (params, trailer));
        }
        let mut xedit_rule: HashMap<String, ParamEnc> = HashMap::new();
        for (k, v) in e.get("xedit_types").and_then(Value::as_object).into_iter().flatten() {
            if let Some(s) = v.as_str() {
                xedit_rule.insert(k.clone(), parse_enc(s)?);
            }
        }
        for (kind, codes) in e.get("enums").and_then(Value::as_object).into_iter().flatten() {
            let m = t.enums.entry(kind.clone()).or_default();
            for (code, name) in codes.as_object().into_iter().flatten() {
                let c: u16 = code.parse().map_err(|_| TableError::Format(format!("enums.{kind}: bad code {code:?}")))?;
                if let Some(n) = name.as_str() {
                    m.insert(c, n.to_string());
                }
            }
        }
        let comp = e.get("compiler");
        let hex_keys = |k: &str| -> Result<HashMap<u16, Value>, TableError> {
            comp.and_then(|c| c.get(k))
                .and_then(Value::as_object)
                .into_iter()
                .flatten()
                .map(|(op, v)| {
                    parse_hex16(op)
                        .map(|o| (o, v.clone()))
                        .ok_or_else(|| TableError::Format(format!("encodings: compiler.{k}: bad opcode {op:?}")))
                })
                .collect()
        };
        let param_counts = hex_keys("param_counts")?;
        let blocks = hex_keys("block")?;
        let number_types = hex_keys("number_types")?;
        for c in strings(comp.and_then(|c| c.get("begin_params"))) {
            let code = parse_hex16(&c).ok_or_else(|| TableError::Format(format!("encodings: begin_params: bad code {c:?}")))?;
            t.begin_params.insert(code);
        }
        let funcs: Vec<&Value> = f.get("functions").and_then(Value::as_array).into_iter().flatten().collect();
        let mut console: Vec<usize> = (0..funcs.len())
            .filter(|&i| {
                strings(funcs[i].get("opcodes")).is_empty()
                    && strings(funcs[i].get("categories")).iter().any(|c| c == "Console Functions")
            })
            .collect();
        let lower = |i: usize| funcs[i].get("name").and_then(Value::as_str).unwrap_or_default().to_ascii_lowercase();
        console.sort_by_key(|&i| lower(i));
        let console_ops: HashMap<usize, u16> =
            console.iter().enumerate().map(|(n, &i)| (i, CONSOLE_OPCODE_BASE + n as u16)).collect();
        for (i, func) in funcs.iter().enumerate() {
            let mut ops: Vec<u16> = strings(func.get("opcodes")).iter().filter_map(|s| parse_hex16(s)).collect();
            ops.extend(console_ops.get(&i));
            if ops.is_empty() {
                continue;
            }
            let name = func.get("name").and_then(Value::as_str).unwrap_or_default().to_string();
            let params: Vec<Param> = func
                .get("params")
                .and_then(Value::as_array)
                .into_iter()
                .flatten()
                .map(|p| Param {
                    name: p.get("name").and_then(Value::as_str).unwrap_or_default().to_string(),
                    wiki_type: p.get("type").and_then(Value::as_str).map(str::to_string),
                    kind: p.get("kind").and_then(Value::as_str).unwrap_or("unknown").to_string(),
                    optional: p.get("optional").and_then(Value::as_bool).unwrap_or(false),
                })
                .collect();
            let xedit_types = strings(func.get("xedit_param_types"));
            let n = |k: &str| func.get(k).and_then(Value::as_u64).unwrap_or(0);
            for &op in &ops {
                let (encodings, trailer, source) = if let Some((p, tr)) = observed.get(&op) {
                    (p.clone(), tr.clone(), EncodingSource::Observed)
                } else if n("script_calls") > 0 {
                    // Called by shipped scripts and not listed: every call decodes with
                    // tagged values only.
                    (Vec::new(), Vec::new(), EncodingSource::Observed)
                } else if xedit_types.iter().any(|x| xedit_rule.contains_key(x)) {
                    let p = xedit_types.iter().map(|x| xedit_rule.get(x).cloned().unwrap_or(ParamEnc::Value)).collect();
                    (p, Vec::new(), EncodingSource::XeditType)
                } else {
                    (Vec::new(), Vec::new(), EncodingSource::Default)
                };
                let fun = Function {
                    opcode: op,
                    name: name.clone(),
                    aliases: strings(func.get("aliases")),
                    observed_spellings: strings(func.get("observed_spellings")),
                    params: params.clone(),
                    calling_reference: func.get("calling_reference").and_then(Value::as_str).map(str::to_string),
                    condition_index: func.get("condition_index").and_then(Value::as_u64).map(|v| v as u16),
                    script_calls: n("script_calls"),
                    scripts_using: n("scripts_using"),
                    condition_uses: n("condition_uses"),
                    console_only: func.get("console_only").and_then(Value::as_bool).unwrap_or(false),
                    encodings,
                    trailer,
                    encoding_source: source,
                    param_count: param_counts.get(&op).and_then(Value::as_u64).map(|n| n as usize),
                    block: blocks.get(&op).and_then(Value::as_bool),
                    number_types: number_types
                        .get(&op)
                        .and_then(Value::as_object)
                        .into_iter()
                        .flatten()
                        .filter_map(|(k, v)| Some((k.parse().ok()?, v.as_str()? == "float")))
                        .collect(),
                };
                for s in std::iter::once(&fun.name).chain(&fun.aliases).chain(&fun.observed_spellings) {
                    t.by_name.entry(s.to_ascii_lowercase()).or_insert(op);
                }
                t.functions.insert(op, fun);
            }
        }
        for op in observed.keys() {
            if !t.functions.contains_key(op) {
                return Err(TableError::Format(format!("encodings: opcode 0x{op:04X} is not in functions.json")));
            }
        }
        Ok(t)
    }

    pub fn get(&self, opcode: u16) -> Option<&Function> {
        self.functions.get(&opcode)
    }

    /// Opcode of a function by name, alias or observed spelling (case-insensitive).
    pub fn by_name(&self, name: &str) -> Option<u16> {
        self.by_name.get(&name.to_ascii_lowercase()).copied()
    }

    /// Encoding of parameter `position` (0-based) of `opcode`; unknown opcodes and
    /// positions beyond the list are tagged values.
    pub fn param_enc(&self, opcode: u16, position: usize) -> ParamEnc {
        self.get(opcode).and_then(|f| f.encodings.get(position).cloned()).unwrap_or(ParamEnc::Value)
    }

    pub fn trailer(&self, opcode: u16) -> &[TrailerEnc] {
        self.get(opcode).map(|f| f.trailer.as_slice()).unwrap_or(&[])
    }

    pub fn block_name(&self, code: u16) -> Option<&str> {
        self.blocks.get(&code).map(String::as_str)
    }

    pub fn enum_name(&self, kind: &str, code: u16) -> Option<&str> {
        self.enums.get(kind)?.get(&code).map(String::as_str)
    }
}
